import React from 'react';

import styles from '../../css/Tradings-ligth.module.css'

import Prods from '../Prods/ProdsLigth';

const TradingsLigth = () => {
  return (
    <div className='container'>
      <div className={styles.tredings-light}>
        <div className={styles['tredings-title']}>Trending</div>
        <ul className={styles.prodbox}>
          <li className={styles.prodbox_item}><Prods /></li>
          <li className={styles.prodbox_item}><Prods /></li>
          <li className={styles.prodbox_item}><Prods /></li>
          <li className={styles.prodbox_item}><Prods /></li>
        </ul>
        <button className={styles.tradings_btn + ' ' + "button"}>See more</button>
      </div>
    </div>
  );
}

export default TradingsLigth;
